const tasks = await query('com.example.type.task', { status: 'open' });
const results = [];
for (const t of tasks) {
  const score = await ops['com-example-operation-score']({ title: t.title });
  results.push({ title: t.title, score });
  update(t, (o) => { o.priority = score; });
}
await flush();
for (const r of results) print(r.title, '=>', r.score);
const top = results.slice().sort((a,b) => b.score - a.score)[0];
print('TOP:', top.title, top.score);
